import { useState } from 'react';
import './ChipBar.css';

export interface ChipBarProps {
  labels: string[];
}

// Visual-only: tracks which chip is pressed locally.
// Grid filtering is wired by a separate part of the codebase.
export function ChipBar({ labels }: ChipBarProps): JSX.Element {
  const [pressed, setPressed] = useState<string | null>(null);

  function handleClick(label: string): void {
    setPressed(prev => (prev === label ? null : label));
  }

  return (
    <div className="chip-bar" role="toolbar" aria-label="Filter chips">
      {labels.map(label => (
        <button
          key={label}
          type="button"
          className="chip-bar__chip"
          aria-pressed={pressed === label}
          onClick={() => handleClick(label)}
        >
          {label}
        </button>
      ))}
    </div>
  );
}
